/**
 * Intersects safe RDF-term equality filters with an existing finite VALUES relation when its rows can be preserved.
 */
final class FilterInValuesOptimizer implements QueryOptimizer {

	private static final int MAX_VALUES = 64;

	@Override
	public void optimize(TupleExpr tupleExpr, Dataset dataset, BindingSet bindings) {
		QueryAlgebraBindingAnalysis analysis = QueryAlgebraBindingAnalysis.withBindingValues(tupleExpr, bindings);
		tupleExpr.visit(new Visitor(analysis));
	}

	private static final class Visitor extends AbstractSimpleQueryModelVisitor<RuntimeException> {
		private final QueryAlgebraBindingAnalysis analysis;

		private Visitor(QueryAlgebraBindingAnalysis analysis) {
			super(false);
			this.analysis = analysis;
		}

		@Override
		public void meet(Filter filter) {
			super.meet(filter);
			if (filter.getParentNode() == null || isScopeBoundary(filter)
					|| !QueryEvaluationUtility.isRepeatable(filter.getArg())) {
				return;
			}
			var bindingScope = FilterBindingScope.resolve(filter);
			if (!bindingScope.retainsAllBindings()
					&& !bindingScope.bindingNames().containsAll(VarNameCollector.process(filter.getCondition()))) {
				return;
			}

			BindingSetAssignment assignment = safeValuesAnchor(filter.getCondition());
			if (assignment == null) {
				return;
			}

			QueryAlgebraBindingAnalysis.ReadOnlyContext input = analysis.contextAt(filter.getArg());
			QueryAlgebraBindingAnalysis.OutputFacts facts = analysis.outputFacts(filter.getArg(), input);
			if (!facts.possibleOutputsKnown() || !facts.guaranteedOutputsKnown()
					|| !analysis.guaranteedAfter(facts).containsAll(assignment.getBindingNames())) {
				return;
			}

			// A new leading VALUES row would become a local binding and could replace the producer's observable
			// representative. The original FILTER remains authoritative unless an existing relation proves the domain.
			if (mergeWithExistingValuesAnchor(filter, assignment)) {
				analysis.invalidate();
			}
		}
	}

	private static boolean isScopeBoundary(Filter filter) {
		return filter != null && filter.isVariableScopeChange();
	}

	private static BindingSetAssignment safeValuesAnchor(ValueExpr condition) {
		if (condition instanceof ListMemberOperator) {
			return listValuesAnchor((ListMemberOperator) condition);
		}
		if (condition instanceof Compare compare && compare.getOperator() == Compare.CompareOp.EQ) {
			return singleValueAnchor(compare.getLeftArg(), compare.getRightArg());
		}
		if (condition instanceof SameTerm sameTerm) {
			return singleValueAnchor(sameTerm.getLeftArg(), sameTerm.getRightArg());
		}
		return null;
	}

	private static BindingSetAssignment listValuesAnchor(ListMemberOperator operator) {
		List<ValueExpr> arguments = operator.getArguments();
		if (arguments == null || arguments.size() < 2 || !(arguments.getFirst() instanceof Var var)) {
			return null;
		}

		if (var.hasValue() || var.getName() == null) {
			return null;
		}

		LinkedHashSet<Value> values = new LinkedHashSet<>();
		for (int i = 1; i < arguments.size(); i++) {
			if (!(arguments.get(i) instanceof ValueConstant)) {
				return null;
			}
			Value value = ((ValueConstant) arguments.get(i)).getValue();
			if (!isSafeValuesAnchorValue(value)) {
				return null;
			}
			values.add(value);
			if (values.size() > MAX_VALUES) {
				return null;
			}
		}
		return valuesAnchor(var.getName(), values);
	}

	private static boolean mergeWithExistingValuesAnchor(Filter filter, BindingSetAssignment assignment) {
		String bindingName = singleBindingName(assignment);
		if (bindingName == null) {
			return false;
		}
		// A later assignment of the same name can replace a VALUES result, and pruning individual rows must not
		// suppress query-fatal work. The injection proof is deliberately stronger than this intersection needs.
		if (!QueryEvaluationUtility.permitsBindingInjection(filter.getArg(), Set.of(bindingName))
				|| !QueryEvaluationUtility.canDiscardWithoutEvaluation(filter.getArg())) {
			return false;
		}

		BindingSetAssignment existingAssignment = findExistingValuesAnchor(filter.getArg(), bindingName);
		if (existingAssignment == null) {
			return false;
		}

		LinkedHashSet<Value> allowedValues = valuesForBinding(assignment, bindingName);
		List<BindingSet> mergedBindingSets = new ArrayList<>();
		Set<String> survivingPossibleNames = new HashSet<>();
		for (BindingSet bindingSet : existingAssignment.getBindingSets()) {
			Value value = bindingSet.getValue(bindingName);
			if (allowedValues.contains(value)) {
				mergedBindingSets.add(bindingSet);
				for (String name : bindingSet.getBindingNames()) {
					if (bindingSet.getValue(name) != null) {
						survivingPossibleNames.add(name);
					}
				}
			}
		}

		if (mergedBindingSets.isEmpty()) {
			filter.replaceWith(new EmptySet());
			return true;
		}
		// VALUES marks its complete possible-name set LOCAL even on an UNDEF row. Removing the only row binding a
		// different column would otherwise resurrect a hidden request parameter in an accepted row.
		if (!existingAssignment.getPossibleBindingNames().equals(survivingPossibleNames)) {
			return false;
		}

		existingAssignment.setBindingSets(List.copyOf(mergedBindingSets));
		filter.replaceWith(filter.getArg().clone());
		return true;
	}

	private static BindingSetAssignment findExistingValuesAnchor(TupleExpr tupleExpr, String bindingName) {
		if (tupleExpr instanceof BindingSetAssignment assignment
				&& assignment.hasRepeatableBindingSets()
				&& assignment.getPossibleBindingNames().contains(bindingName)
				&& everyRowDefines(assignment, bindingName)) {
			return assignment;
		}
		if (tupleExpr instanceof Join join) {
			BindingSetAssignment left = findExistingValuesAnchor(join.getLeftArg(), bindingName);
			if (left != null) {
				return left;
			}
			return findExistingValuesAnchor(join.getRightArg(), bindingName);
		}
		return null;
	}

	private static boolean everyRowDefines(BindingSetAssignment assignment, String bindingName) {
		for (BindingSet row : assignment.getBindingSets()) {
			if (row == null || row.getValue(bindingName) == null) {
				return false;
			}
		}
		return true;
	}

	private static String singleBindingName(BindingSetAssignment assignment) {
		Set<String> bindingNames = assignment.getBindingNames();
		if (bindingNames.size() != 1) {
			return null;
		}
		return bindingNames.iterator().next();
	}

	private static LinkedHashSet<Value> valuesForBinding(BindingSetAssignment assignment, String bindingName) {
		LinkedHashSet<Value> values = new LinkedHashSet<>();
		for (BindingSet bindingSet : assignment.getBindingSets()) {
			values.add(bindingSet.getValue(bindingName));
		}
		return values;
	}

	private static BindingSetAssignment singleValueAnchor(ValueExpr left, ValueExpr right) {
		if (left instanceof Var && right instanceof ValueConstant) {
			return singleValueAnchor((Var) left, (ValueConstant) right);
		}
		if (right instanceof Var && left instanceof ValueConstant) {
			return singleValueAnchor((Var) right, (ValueConstant) left);
		}
		return null;
	}

	private static BindingSetAssignment singleValueAnchor(Var var, ValueConstant constant) {
		if (var.hasValue() || var.getName() == null || !isSafeValuesAnchorValue(constant.getValue())) {
			return null;
		}
		LinkedHashSet<Value> values = new LinkedHashSet<>();
		values.add(constant.getValue());
		return valuesAnchor(var.getName(), values);
	}

	private static BindingSetAssignment valuesAnchor(String bindingName, LinkedHashSet<Value> values) {
		if (values.isEmpty()) {
			return null;
		}

		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingNames(Set.of(bindingName));
		List<String> bindingNames = List.of(bindingName);
		List<BindingSet> bindingSets = new ArrayList<>(values.size());
		for (Value value : values) {
			bindingSets.add(new ListBindingSet(bindingNames, List.of(value)));
		}
		assignment.setBindingSets(List.copyOf(bindingSets));
		return assignment;
	}

	private static boolean isSafeValuesAnchorValue(Value value) {
		return value instanceof IRI || value instanceof Literal && !isUnsafeCoreInEqualityValue((Literal) value);
	}

	private static boolean isUnsafeCoreInEqualityValue(Literal literal) {
		CoreDatatype coreDatatype = literal.getCoreDatatype();
		if (!coreDatatype.isXSDDatatype()) {
			return false;
		}
		CoreDatatype.XSD xsdDatatype = coreDatatype.asXSDDatatypeOrNull();
		return xsdDatatype.isNumericDatatype() || xsdDatatype.isCalendarDatatype()
				|| xsdDatatype.isDurationDatatype() || xsdDatatype == CoreDatatype.XSD.BOOLEAN;
	}
}
